SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.CREATED_TIME DESC) AS rnum, A.auction_id, A.judge_kind_name, A.kind, A.title, A.description, A.initial_price, A.buy_now_price, A.grade, A.current_bid_price, A.weight, A.end_date, I.IMAGE_ID, I.IMAGE_URL, U.user_name FROM AUCTIONS A LEFT JOIN PRODUCT_IMAGES I ON A.auction_id = I.PRODUCT_ID AND I.IS_THUMBNAIL = 'y' INNER JOIN USERS U ON A.seller_id = U.id
A.auction_status = 'on'
AND A.judge_kind_name = #{kind}
) WHERE rnum BETWEEN #{pageable.offset} + 1 AND #{pageable.offset} + #{pageable.size} ORDER BY AUCTION_ID ASC

